{"test_range": "tests/models/transformers/fusers/test_linear.py:854-895", "module_conditions": [], "decorators": ["pytest.mark.parametrize('attn_cls', [FakeAttention, ReversedFakeAttention])", "pytest.mark.parametrize('kv_heads', [4, 2])"], "class_conditions": [], "class_decorators": [], "module_guards": [], "supporting_classes": [{"source": "tests/models/transformers/fusers/test_linear.py:30", "body": "class SiluAndMulStub(nn.Module):
    """Stand-in for vLLM's `SiluAndMul` (no vLLM config required)."""

    def forward(self, x: torch.Tensor) -> torch.Tensor:
