        )
        return self.o_proj(attn_output.reshape(*input_shape, -1)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:196", "body": "class FourParallelLinears(nn.Module):
    """Four same-input projections of different widths -> one merged linear."""

    def __init__(self):
        super().__init__()
        self.proj_a = nn.Linear(8, 4)
        self.proj_b = nn.Linear(8, 6)
        self.proj_c = nn.Linear(8, 8)
        self.proj_d = nn.Linear(8, 10)

    def forward(self, x):
        return self.proj_a(x), self.proj_b(x), self.proj_c(x), self.proj_d(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:210", "body": "class GuardedParallelLinears(FourParallelLinears):
    """A projection referenced by an existence guard as well as its call."""

    def forward(self, x):
        d = self.proj_d(x) if self.proj_d is not None else None
        return self.proj_a(x), self.proj_b(x), self.proj_c(x), d"}, {"source": "tests/models/transformers/fusers/test_linear.py:218", "body": "class MutatingParallelLinears(FourParallelLinears):
    def forward(self, x):
        a = self.proj_a(x)
        x.add_(1)
        return a, self.proj_b(x), self.proj_c(x), self.proj_d(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:225", "body": "class AliasMutatingParallelLinears(FourParallelLinears):
    """A view of the input is mutated between the projections."""

    def forward(self, x):
        a = self.proj_a(x)
        alias = x.view(-1)
        alias.mul_(2)
        return a, self.proj_b(x), self.proj_c(x), self.proj_d(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:235", "body": "class FunctionalInplaceParallelLinears(FourParallelLinears):
    """The input is mutated by a functional in-place call between projections."""

