    """GLU-shaped, but the "activation" is not a known activation module."""

    def __init__(self):
        super().__init__()
        self.act_fn = nn.Dropout()"}, {"source": "tests/models/transformers/fusers/test_linear.py:89", "body": "class BroadcastGLU(NoDownGLU):
    """A broadcast multiply cannot use an equal-halves AndMul kernel."""

    def __init__(self):
