        return q + 2 * k + 3 * v"}, {"source": "tests/models/transformers/fusers/test_linear.py:720", "body": "class FakeMQASelfAttn(FakeSelfAttn):
    """Stand-in for grouped/multi-query layouts, where `k`/`v` are narrower."""

    def forward(self, q, k, v):
        groups = q.shape[-1] // k.shape[-1]
        return q + (2 * k + 3 * v).repeat(1, groups)"}], "input_and_call_source": "def test_bypass_existence_guard_folds_bare_if_statement():
    """A statement-form `if self.<name>:` folds its test to `True`.

    The `len(node.ops) == 1` `Compare` scan skips it (it is not a comparison at
    all); `_in_boolean_context` then matches the `if`'s test and folds it, so the
    bare-truthiness statement form is handled, not silently dropped."""
    funcdef = ast.parse(
        "def f(self, a, b):\n    if self.v_proj:\n        return a\n    return b"
    ).body[0]
    assert isinstance(funcdef, ast.FunctionDef)
    ref = next(
        node
        for node in ast.walk(funcdef)
        if isinstance(node, ast.Attribute) and node.attr == "v_proj"
    )
    bypass_existence_guard(funcdef, ref, "v_proj")
    test = next(node for node in ast.walk(funcdef) if isinstance(node, ast.If)).test
    assert isinstance(test, ast.Constant) and test.value is True", "helpers": [{"source": "tests/models/transformers/fusers/test_linear.py:729", "body": "def _clear_fuser_cache():
