{"test_range": "tests/models/transformers/fusers/test_linear.py:1137-1149", "module_conditions": [], "decorators": ["pytest.mark.parametrize('cls', [MutatingParallelLinears, AliasMutatingParallelLinears, FunctionalInplaceParallelLinears, UnderscoreInplaceParallelLinears])"], "class_conditions": [], "class_decorators": [], "module_guards": [], "supporting_classes": [{"source": "tests/models/transformers/fusers/test_linear.py:30", "body": "class SiluAndMulStub(nn.Module):
    """Stand-in for vLLM's `SiluAndMul` (no vLLM config required)."""

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        d = x.shape[-1] // 2
