        )
        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        return self.o_proj(attn_output), attn_weights"}, {"source": "tests/models/transformers/fusers/test_linear.py:174", "body": "class ReversedFakeAttention(FakeAttention):
