        F.relu(x, inplace=True)
        return a, self.proj_b(x), self.proj_c(x), self.proj_d(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:244", "body": "class UnderscoreInplaceParallelLinears(FourParallelLinears):
    """The input is mutated by a free in-place function between projections."""

    def forward(self, x):
        a = self.proj_a(x)
        torch.relu_(x)
        return a, self.proj_b(x), self.proj_c(x), self.proj_d(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:253", "body": "class PlainQKV(nn.Module):
    """q/k/v returned as a bare tuple: no reshape stands between the calls and
    the return, so both QKVFuser and MergedColumnParallelFuser can rewrite it."""

    def __init__(self, hidden: int = 32, heads: int = 4, head_dim: int = 8):
        super().__init__()
        self.q_proj = nn.Linear(hidden, heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden, heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden, heads * head_dim, bias=False)
        self.head_dim = head_dim

    def forward(self, x):
        return self.q_proj(x), self.k_proj(x), self.v_proj(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:268", "body": "class ExtraProjAttention(FakeAttention):
    """A second non-qkv linear of a different width -> `o_proj` still found."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.sink_proj = nn.Linear(self.head_dim, self.head_dim, bias=False)"}, {"source": "tests/models/transformers/fusers/test_linear.py:276", "body": "class QKNormAttention(FakeAttention):
    """OLMoE-style: a full-dim norm applied to the whole q/k projection output."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.q_norm = nn.RMSNorm(self.q_proj.out_features)
        self.k_norm = nn.RMSNorm(self.k_proj.out_features)

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        q = self.q_norm(self.q_proj(hidden_states))
        k = self.k_norm(self.k_proj(hidden_states))
        v = self.v_proj(hidden_states)
        return self.o_proj(q + k + v), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:293", "body": "class PerHeadQKNormAttention(FakeAttention):
    """Qwen3-style: a per-head norm (`head_dim`) applied after the head reshape."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.q_norm = nn.RMSNorm(self.head_dim)
        self.k_norm = nn.RMSNorm(self.head_dim)

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        shape = (*hidden_states.shape[:-1], -1, self.head_dim)
        q = self.q_norm(self.q_proj(hidden_states).view(shape))
        k = self.k_norm(self.k_proj(hidden_states).view(shape))
        v = self.v_proj(hidden_states).view(shape)
        return self.o_proj((q + k + v).flatten(-2)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:311", "body": "class ResidDropoutAttention(FakeAttention):
    """GPT-style dropout after `o_proj` -> the output projection is still found."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
