{"test_range": "tests/models/transformers/fusers/test_linear.py:1290-1303", "module_conditions": [], "decorators": [], "class_conditions": [], "class_decorators": [], "module_guards": [], "supporting_classes": [{"source": "tests/models/transformers/fusers/test_linear.py:30", "body": "class SiluAndMulStub(nn.Module):
    """Stand-in for vLLM's `SiluAndMul` (no vLLM config required)."""

