        self.v_proj = nn.Linear(hidden, heads * head_dim, bias=False)
        self.head_dim = head_dim

    def forward(self, x):
        return self.q_proj(x), self.k_proj(x), self.v_proj(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:268", "body": "class ExtraProjAttention(FakeAttention):
    """A second non-qkv linear of a different width -> `o_proj` still found."""

    def __init__(self, **kwargs):
