    """Qwen3-style: a per-head norm (`head_dim`) applied after the head reshape."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.q_norm = nn.RMSNorm(self.head_dim)
        self.k_norm = nn.RMSNorm(self.head_dim)

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        shape = (*hidden_states.shape[:-1], -1, self.head_dim)
        q = self.q_norm(self.q_proj(hidden_states).view(shape))
        k = self.k_norm(self.k_proj(hidden_states).view(shape))
        v = self.v_proj(hidden_states).view(shape)
        return self.o_proj((q + k + v).flatten(-2)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:311", "body": "class ResidDropoutAttention(FakeAttention):
    """GPT-style dropout after `o_proj` -> the output projection is still found."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.resid_dropout = nn.Dropout(0.0)

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        return self.resid_dropout(self.o_proj(attn_output)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:338", "body": "class GuardedVAttention(FakeAttention):
    """Gemma 4-style: `v_proj` is called once but also read in a `None` guard.

    The guard is a fusion invariant (the fuser only binds instances where the
    projection exists), so it folds to `True` and the call still fuses."""

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = (
            self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
            if self.v_proj is not None
            else k
        )
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1).contiguous()), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:367", "body": "class TruthyGuardAttention(FakeAttention):
    """`v_proj` guarded by a bare truthiness test instead of `is not None`.

    An `nn.Linear` is always truthy, so the guard folds to `True` and the call
    still fuses (the projection is a proven invariant, exactly as for a `None`
    guard)."""

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = (
            self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
            if self.v_proj
            else k
        )
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1).contiguous()), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:397", "body": "class StatementGuardVAttention(FakeAttention):
    """`v_proj` guarded by a statement-form `if self.v_proj:` block.

    The `if`'s test is not an `ast.Compare`, so the identity-check scan skips it;
    `_in_boolean_context` folds the test to `True` (an `nn.Linear` is always
    truthy) and the call inside the now-`if True:` body still fuses, with the
    live `else` surviving the rewrite."""

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        if self.v_proj:
            v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        else:
            v = k
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1).contiguous()), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:427", "body": "class BranchedKVAttention(FakeAttention):
    """Gemma 4-style: q at body level, k/v inside an untaken `else` branch.

    The three calls do not share a block, so the fused GEMM must be hoisted to
    the innermost block that dominates all of them (the function body). The
    live `if`/`else` must survive the rewrite."""

    is_kv_shared_layer = False

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        if self.is_kv_shared_layer:
            k = v = None
        else:
            k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
            v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1).contiguous()), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:458", "body": "class RebindArgAttention(FakeAttention):
    """The projection input is rebound (in an untaken branch) before k/v.

    The branch is dead at trace time so the match succeeds, but the source
    rewrite must refuse: hoisting the GEMM above the rebind would feed k/v a
    different input. Result: no fusion."""

    recompute = False

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        if self.recompute:
            hidden_states = hidden_states * 2
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:488", "body": "class InPlaceMutatedArgAttention(FakeAttention):
    """The shared input is mutated in place (in an untaken branch) before k/v.

    Like `RebindArgAttention`, but the mutation keeps the name in a `Load`
    context (`hidden_states.mul_(2)`), so a bare `Name`-store check would miss it.
    The rewrite must still refuse: hoisting the GEMM above the mutation changes
    the value k/v see. Result: no fusion."""

    recompute = False

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        if self.recompute:
            hidden_states.mul_(2)
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:519", "body": "class AliasMutatedArgAttention(FakeAttention):
    """A view of the shared input is mutated before k/v.

    `hidden_states.view(-1)` shares storage with its base, so `alias.mul_(2)`
    changes what k/v read without ever naming `hidden_states` as a target. Only
    tracking names that may alias the input catches it. Result: no fusion."""

    recompute = False

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        if self.recompute:
            alias = hidden_states.view(-1)
            alias.mul_(2)
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:550", "body": "class FunctionalInplaceArgAttention(FakeAttention):
    """The shared input is mutated by a functional in-place call before k/v.

    `F.relu(hidden_states, inplace=True)` writes through an argument, so the
    name appears only in a `Load` context inside a call that is not a method on
    it -- invisible to a trailing-underscore method check. Result: no fusion."""

    recompute = False

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        if self.recompute:
            F.relu(hidden_states, inplace=True)
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:580", "body": "class SubscriptMutatedArgAttention(FakeAttention):
    """The shared input is written through a subscript (in an untaken branch).

    `hidden_states[..., 0] = 0` leaves the name in a `Load` context on the
    subscript's value, so it too evades a bare `Name`-store check. The rewrite
    must refuse for the same reason. Result: no fusion."""

    recompute = False

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        if self.recompute:
            hidden_states[..., 0] = 0
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:610", "body": "class NonFoldableRefAttention(FakeAttention):
    """A surviving `v_proj` reference that is not an existence guard -> no fusion.

    Deleting `v_proj` would break `isinstance(self.v_proj, nn.Linear)`: it reads
    the projection's type, not just whether it exists, so the fuser cannot fold
    it and must refuse rather than rewrite it."""

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        q = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        k = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        v = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        if isinstance(self.v_proj, nn.Linear):
            v = v.contiguous()
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, _ = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        return self.o_proj(attn_output.reshape(*input_shape, -1)), None"}, {"source": "tests/models/transformers/fusers/test_linear.py:638", "body": "class PackedQKVAttention(nn.Module):
    """GPTBigCode-style: one packed projection split into q/k/v in the forward."""

    is_causal = True

    def __init__(
        self,
        hidden: int = 32,
        head_dim: int = 8,
        heads: int = 4,
        kv_heads: int = 1,
        bias: bool = False,
        layer_idx: int = 0,
    ):
        super().__init__()
        self.config = SimpleNamespace(_attn_implementation="vllm")
        self.layer_idx = layer_idx
        self.head_dim = head_dim
        self.scaling = head_dim**-0.5
        self.embed_dim = heads * head_dim
        self.kv_dim = kv_heads * head_dim
        self.c_attn = nn.Linear(hidden, self.embed_dim + 2 * self.kv_dim, bias=bias)
        self.c_proj = nn.Linear(self.embed_dim, hidden, bias=bias)
        self.resid_dropout = nn.Dropout(0.0)

    def forward(
        self, hidden_states, attention_mask=None, past_key_values=None, **kwargs
    ):
        from transformers.modeling_utils import ALL_ATTENTION_FUNCTIONS

        input_shape = hidden_states.shape[:-1]
        q, k, v = (
            self.c_attn(hidden_states)
            .unsqueeze(1)
            .split((self.embed_dim, self.kv_dim, self.kv_dim), dim=3)
        )
        q = q.view(*input_shape, -1, self.head_dim).transpose(1, 2)
        if past_key_values is not None:
            k, v = past_key_values.update(k, v, self.layer_idx)
        attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, None
        )
        attn_output, attn_weights = attention_interface(
            self, q, k, v, attention_mask, scaling=self.scaling, **kwargs
        )
        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        return self.resid_dropout(self.c_proj(attn_output)), attn_weights"}, {"source": "tests/models/transformers/fusers/test_linear.py:687", "body": "class PerHeadSplitAttention(nn.Module):
    """A packed projection reshaped and split *per head* -> not a q/k/v split."""

    def __init__(self, hidden: int = 32, head_dim: int = 8, heads: int = 4):
        super().__init__()
        self.head_dim = head_dim
        self.heads = heads
        self.c_attn = nn.Linear(hidden, 3 * heads * head_dim)
        self.c_proj = nn.Linear(heads * head_dim, hidden)

    def forward(self, hidden_states):
        shape = (*hidden_states.shape[:2], self.heads, 3 * self.head_dim)
        q, k, v = (
            self.c_attn(hidden_states)
            .view(shape)
            .transpose(1, 2)
            .split((self.head_dim, self.head_dim, self.head_dim), dim=3)
        )
        return self.c_proj((q + k + v).transpose(1, 2).flatten(-2))"}, {"source": "tests/models/transformers/fusers/test_linear.py:708", "body": "class FakeSelfAttn(nn.Module):
    """Stand-in for the vLLM `Attention` attached to the dispatching module."""

    def __init__(self):
        super().__init__()
        self.impl = SimpleNamespace(scale=None)

    def forward(self, q, k, v):
        # MHA-shaped stub: any deterministic combination of q/k/v will do
        return q + 2 * k + 3 * v"}, {"source": "tests/models/transformers/fusers/test_linear.py:720", "body": "class FakeMQASelfAttn(FakeSelfAttn):
    """Stand-in for grouped/multi-query layouts, where `k`/`v` are narrower."""

    def forward(self, q, k, v):
        groups = q.shape[-1] // k.shape[-1]
        return q + (2 * k + 3 * v).repeat(1, groups)"}], "input_and_call_source": "def test_weight_mappings_are_scoped_to_fused_prefixes():
    from vllm.model_executor.models.utils import WeightsMapper

    with torch.device("meta"):
        glu_fuser = get_fuser(GLUMLP(), GLUFuser)
        qkv_fuser = get_fuser(FakeAttention(), QKVFuser)
    assert glu_fuser is not None and qkv_fuser is not None

    mapper = WeightsMapper()
    assert isinstance(mapper.orig_to_new_stacked, MutableMapping)
    for prefix in ("model.layers.0.mlp", "model.layers.1.mlp"):
        mapper.orig_to_new_stacked.update(glu_fuser.orig_to_new_stacked(prefix))
    mapper.orig_to_new_stacked.update(
        qkv_fuser.orig_to_new_stacked("model.layers.0.self_attn")
    )

    names = [
        "model.layers.0.mlp.gate_proj.weight",
        "model.layers.0.mlp.up_proj.weight",
        "model.layers.1.mlp.gate_proj.weight",
        "model.layers.0.self_attn.q_proj.weight",
        "model.layers.0.self_attn.k_proj.weight",
        "model.layers.0.self_attn.v_proj.weight",
        # Unfused modules at other prefixes must be left untouched.
        "model.layers.2.mlp.experts.0.gate_proj.weight",
        "model.layers.1.self_attn.q_proj.weight",
    ]
    # `apply` rewrites the name and stamps the shard id onto each tensor.
    weights = [(name, torch.empty(0)) for name in names]
    mapped = list(mapper.apply(weights))
    mapped_names = [name for name, _ in mapped]
    shard_ids = [getattr(data, "shard_id", None) for _, data in mapped]

    assert mapped_names == [
        "model.layers.0.mlp.gate_up_proj.weight",
        "model.layers.0.mlp.gate_up_proj.weight",
        "model.layers.1.mlp.gate_up_proj.weight",
        "model.layers.0.self_attn.qkv_proj.weight",
        "model.layers.0.self_attn.qkv_proj.weight",
        "model.layers.0.self_attn.qkv_proj.weight",
        # Only the exact fused layers are remapped; everything else is untouched.
        "model.layers.2.mlp.experts.0.gate_proj.weight",
        "model.layers.1.self_attn.q_proj.weight",
    ]
    assert shard_ids == [0, 1, 0, "q", "k", "v", None, None]

    # The fused layers are exposed to the quantization machinery via their
    # original constituent projection names (what the checkpoint stores).
    assert glu_fuser.packed_modules_mapping == {
        "gate_up_proj": ["gate_proj", "up_proj"],
    }
    assert qkv_fuser.packed_modules_mapping == {
        "qkv_proj": ["q_proj", "k_proj", "v_proj"],
    }", "helpers": [{"source": "tests/models/transformers/fusers/test_linear.py:729", "body": "def _clear_fuser_cache():
    get_fusers.cache_clear()
    yield
    get_fusers.cache_clear()"}], "implementation_anchors": ["vllm/model_executor/models/transformers/fusers/base.py:155", "vllm/model_executor/models/utils.py:58", "vllm/model_executor/models/transformers/fusers/glu.py:50", "vllm/model_executor/models/transformers/fusers/qkv.py:37"], "external_helper_anchors": [], "external_helper_sources": [], "validation": "仅静态源码核对，未导入或执行上游，未使用GPU"}

{"test_range": "tests/models/transformers/fusers/test_linear.py:1363-1369", "module_conditions": [], "decorators": ["pytest.mark.parametrize('cls', [NotAnMLP, NotAnActGLUMLP, BroadcastGLU])"], "class_conditions": [], "class_decorators": [], "module_guards": [], "supporting_classes": [{"source": "tests/models/transformers/fusers/test_linear.py:30", "body": "class SiluAndMulStub(nn.Module):
    """Stand-in for vLLM's `SiluAndMul` (no vLLM config required)."""

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        d = x.shape[-1] // 2
        return F.silu(x[..., :d]) * x[..., d:]"}, {"source": "tests/models/transformers/fusers/test_linear.py:38", "body": "class NoDownGLU(nn.Module):
    """`act(gate(x)) * up(x)` with no output projection -> `down_name` is None."""

    def __init__(self, hidden: int = 16, inter: int = 32, bias: bool = False):
        super().__init__()
        self.gate_proj = nn.Linear(hidden, inter, bias=bias)
        self.up_proj = nn.Linear(hidden, inter, bias=bias)
        self.act_fn = nn.SiLU()

    def forward(self, x):
        return self.act_fn(self.gate_proj(x)) * self.up_proj(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:51", "body": "class GLUMLP(NoDownGLU):
    """`down(act(gate(x)) * up(x))` — the canonical HF GLU MLP."""

    def __init__(self, hidden: int = 16, inter: int = 32, bias: bool = False):
        super().__init__(hidden, inter, bias)
        self.down_proj = nn.Linear(inter, hidden, bias=bias)

    def forward(self, x):
        return self.down_proj(self.act_fn(self.gate_proj(x)) * self.up_proj(x))"}, {"source": "tests/models/transformers/fusers/test_linear.py:62", "body": "class ReversedGLUMLP(GLUMLP):
    """`up(x) * act(gate(x))` — operands swapped (multiply is commutative)."""

    def forward(self, x):
        return self.down_proj(self.up_proj(x) * self.act_fn(self.gate_proj(x)))"}, {"source": "tests/models/transformers/fusers/test_linear.py:69", "body": "class NotAnMLP(nn.Module):
    """Two linears but no activation*linear multiply -> must not match."""

    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(8, 8)
        self.fc2 = nn.Linear(8, 8)

    def forward(self, x):
