    def forward(self, x):
        return self.proj_a(x), self.proj_b(x), self.proj_c(x), self.proj_d(x)"}, {"source": "tests/models/transformers/fusers/test_linear.py:210", "body": "class GuardedParallelLinears(FourParallelLinears):
    """A projection referenced by an existence guard as well as its call."""

