        return logits.sum()"}, {"source": "tests/models/transformers/fusers/test_moe.py:197", "body": "class MoEBlockShared(MoEBlock):
    """A block with a shared expert and its sigmoid gate (Qwen2-style)."""

    def __init__(self):
        super().__init__()
        self.shared_expert = GLUMLP()
        self.shared_expert_gate = nn.Linear(16, 1, bias=False)

    def _shared(self, x, logits):
        return torch.sigmoid(self.shared_expert_gate(x)) * self.shared_expert(x)"}, {"source": "tests/models/transformers/fusers/test_moe.py:209", "body": "class MoEBlockSharedNoGate(MoEBlock):
