    """Packed experts (3D weights); only its name (`experts`) matters here."""

    def __init__(self, num_experts=8, hidden=16, inter=32):
        super().__init__()
        self.gate_up_proj = nn.Parameter(torch.zeros(num_experts, 2 * inter, hidden))
