{"test_range": "tests/models/transformers/fusers/test_moe.py:549-554", "module_conditions": [], "decorators": [], "class_conditions": [], "class_decorators": [], "module_guards": [], "supporting_classes": [{"source": "tests/models/transformers/fusers/test_moe.py:15", "body": "class TopKRouter(nn.Module):
    """HF v5 top-k router: `linear -> softmax -> topk (-> renorm)`."""

    def __init__(self, num_experts=8, hidden=16, top_k=2, sigmoid=False):
        super().__init__()
        self.top_k = top_k
        self.sigmoid = sigmoid
        self.weight = nn.Parameter(torch.zeros(num_experts, hidden))

    def forward(self, hidden_states):
        logits = F.linear(hidden_states, self.weight)
        scores = torch.sigmoid(logits) if self.sigmoid else F.softmax(logits, dim=-1)
        value, index = torch.topk(scores, self.top_k, dim=-1)
        value = value / value.sum(dim=-1, keepdim=True)
        return logits, value, index"}, {"source": "tests/models/transformers/fusers/test_moe.py:32", "body": "class SelectionScoredRouter(TopKRouter):
    """Scores the selected logits only (GraniteMoE/Aria style), in fp32."""

    def forward(self, hidden_states):
        logits = F.linear(hidden_states, self.weight).float()
        value, index = torch.topk(logits, self.top_k, dim=-1)
        value = (
            torch.sigmoid(value) if self.sigmoid else F.softmax(value, dim=-1)
        ).type_as(hidden_states)
        return logits, value, index"}, {"source": "tests/models/transformers/fusers/test_moe.py:44", "body": "class EpsilonRenormRouter(TopKRouter):
    """Renormalizes via an epsilon-offset denominator (DeepSeek-V3 style)."""

    def forward(self, hidden_states):
        logits = F.linear(hidden_states, self.weight)
        scores = torch.sigmoid(logits)
        value, index = torch.topk(scores, self.top_k, dim=-1)
        denominator = value.sum(dim=-1, keepdim=True) + 1e-20
        value /= denominator
        return logits, value, index"}, {"source": "tests/models/transformers/fusers/test_moe.py:56", "body": "class UntraceableRouter(TopKRouter):
    """Scores and selects, then loses the trace before the renormalization."""

    def forward(self, hidden_states):
        logits = F.linear(hidden_states, self.weight)
        scores = F.softmax(logits, dim=-1)
        value, index = torch.topk(scores, self.top_k, dim=-1)
        if value.sum() > 0:  # data-dependent branch: tracing stops here
            value = value / value.sum(dim=-1, keepdim=True)
        return logits, value, index"}, {"source": "tests/models/transformers/fusers/test_moe.py:68", "body": "class ScaledRouter(TopKRouter):
    """Greedy router scaling its top-k weights (DeepSeek `routed_scaling_factor`)."""

    def forward(self, hidden_states):
        logits = F.linear(hidden_states, self.weight)
        scores = F.softmax(logits, dim=-1)
        value, index = torch.topk(scores, self.top_k, dim=-1)
        value = value * 16.0
        return logits, value, index"}, {"source": "tests/models/transformers/fusers/test_moe.py:79", "body": "class Fp32Router(TopKRouter):
    """Router that computes its logits in fp32 (DeepSeek/GLM style)."""

    def forward(self, hidden_states):
        logits = F.linear(
            hidden_states.type(torch.float32), self.weight.type(torch.float32)
        )
        scores = F.softmax(logits, dim=-1)
        value, index = torch.topk(scores, self.top_k, dim=-1)
        return logits, value.to(hidden_states.dtype), index"}, {"source": "tests/models/transformers/fusers/test_moe.py:91", "body": "class GroupedRouter(TopKRouter):
    """Group-limited router (DeepSeek `group_limited_greedy`), scaled weights."""

    def forward(self, hidden_states):
        logits = F.linear(hidden_states, self.weight)
        scores = F.softmax(logits, dim=-1)
        group_scores = scores.view(-1, 4, 2).max(dim=-1).values
        group_idx = torch.topk(group_scores, k=2, dim=-1)[1]
        group_mask = torch.zeros_like(group_scores)
        group_mask.scatter_(1, group_idx, 1)
        score_mask = group_mask.unsqueeze(-1).expand(-1, 4, 2).reshape(-1, 8)
        scores = scores.masked_fill(~score_mask.bool(), 0.0)
        value, index = torch.topk(scores, self.top_k, dim=-1)
        value = value * 16.0
        return logits, value, index"}, {"source": "tests/models/transformers/fusers/test_moe.py:108", "body": "class CorrectionRouter(nn.Module):
