{"test_range": "tests/models/transformers/fusers/test_rms_norm.py:217-221", "module_conditions": [], "decorators": ["pytest.mark.parametrize('cls,eps,zero_centered', [(RMSNorm, 1e-05, False), (GemmaRMSNorm, 1e-06, True), (WeightlessRMSNorm, 1e-06, False), (Gemma4RMSNorm, 1e-06, False), (PowOperatorRMSNorm, 1e-06, False), (KwargPowRMSNorm, 1e-06, False), (KwargBasePowRMSNorm, 1e-06, False), (WeightlessGemma4RMSNorm, 1e-06, False), (LayerNorm, 1e-06, False), (torch.nn.RMSNorm, 1e-05, False)])"], "class_conditions": [], "class_decorators": [], "module_guards": [], "supporting_classes": [{"source": "tests/models/transformers/fusers/test_rms_norm.py:16", "body": "class RMSNorm(nn.Module):
    """The canonical HF RMSNorm: `weight * x * rsqrt(mean(x**2) + eps)`."""

    def __init__(self, hidden: int = 16, eps: float = 1e-5, weight: bool = True):
        super().__init__()
        if weight:
            self.weight = nn.Parameter(torch.ones(hidden))
        self.variance_epsilon = eps

    def _rms(self, x):
        return x * torch.rsqrt(x.pow(2).mean(-1, keepdim=True) + self.variance_epsilon)

    def forward(self, x):
        return self.weight * self._rms(x.to(torch.float32)).to(x.dtype)"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:32", "body": "class GemmaRMSNorm(RMSNorm):
    """Zero-centered weight: `(1 + weight) * normalized`."""

    def __init__(self, hidden: int = 16, eps: float = 1e-6):
        super().__init__(hidden, eps)
        self.weight = nn.Parameter(torch.zeros(hidden))

    def forward(self, x):
        return (1.0 + self.weight) * self._rms(x.to(torch.float32)).to(x.dtype)"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:43", "body": "class WeightlessRMSNorm(RMSNorm):
    """No scale parameter (e.g. Gemma3n `with_scale=False`)."""

    def __init__(self, hidden: int = 16, eps: float = 1e-6):
        super().__init__(hidden, eps, weight=False)

    def forward(self, x):
        return self._rms(x.to(torch.float32)).to(x.dtype)"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:53", "body": "class Gemma4RMSNorm(RMSNorm):
    """`pow(v, -0.5)` where the others write `rsqrt(v)` (HF `Gemma4RMSNorm._norm`).

    Gemma 4 spells the reciprocal square root as `torch.pow(..., -0.5)` to keep
    Torch and JAX in agreement, and -- unlike Gemma 1-3 -- its weight is *not*
    zero-centered, so this fuses to a plain `RMSNorm`.
    """

    def _rms(self, x):
        mean_squared = x.pow(2).mean(-1, keepdim=True) + self.variance_epsilon
        return x * torch.pow(mean_squared, -0.5)

    def forward(self, x):
        return (self._rms(x.float()) * self.weight.float()).type_as(x)"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:69", "body": "class PowOperatorRMSNorm(Gemma4RMSNorm):
    """The `v ** -0.5` operator spelling of the same reciprocal square root."""

    def _rms(self, x):
        return x * (x.pow(2).mean(-1, keepdim=True) + self.variance_epsilon) ** -0.5"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:76", "body": "class KwargPowRMSNorm(Gemma4RMSNorm):
    """The keyword spelling `torch.pow(v, exponent=-0.5)` of the same rsqrt."""

    def _rms(self, x):
        mean_squared = x.pow(2).mean(-1, keepdim=True) + self.variance_epsilon
        return x * torch.pow(mean_squared, exponent=-0.5)"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:84", "body": "class KwargBasePowRMSNorm(Gemma4RMSNorm):
    """The fully functional spelling `torch.pow(input=v, exponent=-0.5)`."""

    def _rms(self, x):
        mean_squared = x.pow(2).mean(-1, keepdim=True) + self.variance_epsilon
        return x * torch.pow(input=mean_squared, exponent=-0.5)"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:92", "body": "class WeightlessGemma4RMSNorm(Gemma4RMSNorm):
    """Gemma 4 with `with_scale=False`: the `pow` spelling and no scale parameter."""

