        setattr(self, self.attr, eps)

    def forward(self, x):
        eps = getattr(self, self.attr)
        return self.weight * (x * torch.rsqrt(x.pow(2).mean(-1, True) + eps))"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:127", "body": "class ToleranceRMSNorm(NamedEpsRMSNorm):
