    """eps is a literal in the source, and an unrelated attribute happens to
    hold the same value: matching on the value alone would bind to it."""

    def __init__(self, hidden: int = 16, eps: float = 1e-5):
        super().__init__(hidden, eps)
        self.epsilon_lookalike = 1e-4

    def forward(self, x):
        return self.weight * (x * torch.rsqrt(x.pow(2).mean(-1, True) + 1e-4))"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:145", "body": "class AmbiguousEpsRMSNorm(nn.Module):
    """Two attributes hold the eps value, and the forward reads the second, so
    their order cannot pick it."""

    def __init__(self, hidden: int = 16, eps: float = 1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden))
        self.decoy_eps = eps
        self.variance_epsilon = eps

    def forward(self, x):
        var = x.pow(2).mean(-1, True)
        return self.weight * (x * torch.rsqrt(var + self.variance_epsilon))"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:160", "body": "class NotAnRMSNorm(RMSNorm):
    """Mean-subtracting LayerNorm-like math -> not an RMSNorm."""

    def __init__(self, hidden: int = 16, eps: float = 1e-6):
        super().__init__(hidden, eps)

    def forward(self, x):
        x = x - x.mean(-1, keepdim=True)
        variance = x.var(-1, keepdim=True)
        return self.weight * x / torch.sqrt(variance + self.variance_epsilon)"}, {"source": "tests/models/transformers/fusers/test_rms_norm.py:172", "body": "class GatedRMSNorm(RMSNorm):
    """Second input and tail compute -> not an RMSNorm."""

