    """Matching `pow(v, -0.5)` is only sound if it really is the reciprocal square
    root: the fused norm must reproduce the unfused forward, not just replace it.
    `pow` and `rsqrt` take different paths to the same value, so compare at float32
    tolerance rather than bit-for-bit."""
    torch.manual_seed(0)
    module = cls(16)
    with torch.no_grad():
        module.weight.copy_(torch.randn(16))
    fuser = get_fuser(module, RMSNormFuser)
    assert fuser is not None
    built = fuser.fuse(module, "norm", default_vllm_config)
    with torch.no_grad():
        built.weight.copy_(module.weight)
    x = torch.randn(4, 16)
    torch.testing.assert_close(built(x), module(x), rtol=1e-5, atol=1e-6)", "helpers": [], "implementation_anchors": ["vllm/model_executor/models/transformers/fusers/rms_norm.py:118", "vllm/model_executor/models/transformers/fusers/rms_norm.py:278", "vllm/model_executor/layers/layernorm.py:79", "vllm/ir/ops/layernorm.py:10", "tests/conftest.py:254", "vllm/model_executor/hw_agnostic/_resolve.py:31"], "external_helper_anchors": ["tests/conftest.py:254"], "external_helper_sources": [{"source": "tests/conftest.py:254", "body": "def default_vllm_config():
