    """`torch.nn.RMSNorm` (a single `F.rms_norm` call) matches via the fast path;
    its default `eps=None` resolves to `finfo(dtype).eps` in `fuse`."""
    from vllm.model_executor.layers.layernorm import RMSNorm as VLLMRMSNorm

    with torch.device("meta"):
        module = torch.nn.RMSNorm(16)  # forward is a single `F.rms_norm` call
        fuser = get_fuser(module, RMSNormFuser)
        assert isinstance(fuser, RMSNormFuser)
        assert not fuser.zero_centered
        vllm_config = SimpleNamespace(model_config=SimpleNamespace(dtype=torch.float32))
        built = fuser.fuse(module, "norm", vllm_config)
    assert isinstance(built, VLLMRMSNorm)
    assert built.variance_epsilon == torch.finfo(torch.float32).eps", "helpers": [], "implementation_anchors": ["vllm/model_executor/models/transformers/fuser.py:54", "vllm/model_executor/models/transformers/fusers/rms_norm.py:223", "vllm/model_executor/models/transformers/fusers/rms_norm.py:278", "vllm/model_executor/layers/layernorm.py:48", "vllm/model_executor/layers/layernorm.py:155", "tests/conftest.py:254", "vllm/model_executor/hw_agnostic/_resolve.py:31"], "external_helper_anchors": ["tests/conftest.py:254"], "external_helper_sources": [{"source": "tests/conftest.py:254", "body": "def default_vllm_config():
